def _jt(settings, attr):
    jrv = settings["//command_line_option:java_runtime_version"]
    return {
        "//command_line_option:java_runtime_version": "remotejdk_17",
        "//command_line_option:java_language_version": "17" if jrv == "local_jdk" else "21",
    }

jt = transition(
    implementation = _jt,
    inputs = ["//command_line_option:java_runtime_version"],
    outputs = ["//command_line_option:java_runtime_version", "//command_line_option:java_language_version"],
)

def _tool(settings, attr):
    return {"//command_line_option:tool_java_runtime_version": "remotejdk_17", "//command_line_option:tool_java_language_version": "17"}

tool_t = transition(implementation = _tool, inputs = [], outputs = ["//command_line_option:tool_java_runtime_version", "//command_line_option:tool_java_language_version"])

def _impl(ctx):
    d = ctx.attr.dep
    d = d[0] if type(d) == "list" else d
    return [DefaultInfo(files = d[DefaultInfo].files)]

jt_use = rule(implementation = _impl, attrs = {"dep": attr.label(cfg = jt)})
tool_use = rule(implementation = _impl, attrs = {"dep": attr.label(cfg = tool_t)})

